// Turn a Kavach event into a message. Kavach has already decided; n8n only delivers.
const e = $input.first().json.body || $input.first().json;
const p = e.payload || {};
const lines = {
  followup_scheduled: `Kavach will check back: ${p.summary || ''}`,
  followup_fired: `Follow-up due (${p.via || 'scheduled'}): ${p.purpose || ''}`,
  approval_needed: `Approval needed for ${p.action}: ${(p.approvers || []).join(' + ')}. ${p.reason || ''}`,
  escalation_letter_approved: `Meena approved an escalation letter: ${p.summary || ''}`,
  escalated_to_human: `Escalated to a human: ${p.summary || ''}`,
  evidence_pack_issued: `Signed evidence pack issued: ${p.summary || ''}`,
  payouts_held: `Payouts held in the Paytm settlement balance (two-key approved).`,
  edd_assigned: `EDD review assigned: ${p.merchant} (${(p.signals || []).join(', ')})`,
  refund_initiated: `Refund started: ${p.summary || ''}`,
  case_event_recorded: `Case event recorded: ${p.summary || ''}`
};
const toRisk = ['escalated_to_human', 'edd_assigned', 'approval_needed'].includes(e.event);
return [{ json: {
  event: e.event,
  audience: toRisk ? 'paytm-risk' : 'merchant',
  subject: `[Kavach] ${e.event.replace(/_/g, ' ')} · ${p.incident || p.mid || ''}`,
  text: (lines[e.event] || JSON.stringify(p)) + `\n\nSynthetic demo event from Kavach at ${e.at}.`
} }];
